-- Reference export: seed 42, beta 6, h=3/8; 21 nights ending 2026-10-23.
-- Standalone fallback generated from the whitepaper equations; regenerate via
-- python -m app.routes.demo --export data/seed_demo.sql when M1/M8 are installed.
-- Standalone synthetic demo, users 2/3 only. Apply db/schema.sql first.
BEGIN;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM users WHERE id IN (2,3) AND NOT is_simulated) THEN RAISE EXCEPTION 'Demo IDs belong to a real user'; END IF; END $$;
DELETE FROM drinks WHERE user_id=2;
DELETE FROM alcohol WHERE user_id=2;
DELETE FROM sleep_nights WHERE user_id=2;
DELETE FROM hr_checks WHERE user_id=2;
DELETE FROM drinks WHERE user_id=3;
DELETE FROM alcohol WHERE user_id=3;
DELETE FROM sleep_nights WHERE user_id=3;
DELETE FROM hr_checks WHERE user_id=3;
SELECT setval(pg_get_serial_sequence('users','id'), GREATEST((SELECT MAX(id) FROM users), (SELECT last_value FROM users_id_seq)), true);
COMMIT;
CALL refresh_continuous_aggregate('daily_caffeine', NULL, date_trunc('day', now()));
